Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='preferexistingtools', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='Name the existing tool or library before writing a new mechanism or measurement', body='Before writing a parser, a measurement, a cache or another generic mechanism, find the tool, the provider API or the library that already does it. Say which ones were checked and why each was taken or not. A pull request that adds a few hundred lines of a generic mechanism answers which library was checked.', rationale='A hand-rolled mechanism costs time to run, then again to distrust, and an existing instrument is often better.', supersedes=()))